SELECT 'learn-image-campaign-production-en-v1', `id`, @image_campaign_content,
       'system:learn-content', CURRENT_TIMESTAMP(3)
FROM `LearnPost`
WHERE `id` = 'learn-image-campaign-production-en'
ON DUPLICATE KEY UPDATE `id` = VALUES(`id`);

SET @image_campaign_content = NULL;
